      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    h1 {
      margin: 1rem 0 0.75rem;
      font-size: clamp(2rem, 5vw, 3.5rem);
      line-height: 1.1;
